export async function POST(request: Request) {
  let corps: unknown;
  try { corps = await request.json(); }
  catch { return Response.json({ erreur: "JSON invalide" }, { status: 400 }); }
  if (typeof corps !== "object" || corps === null || !("titre" in corps) ||
      typeof corps.titre !== "string" || !corps.titre.trim() || corps.titre.length > 80) {
    return Response.json({ erreur: "titre invalide" }, { status: 400 });
  }
  return Response.json({ titre: corps.titre.trim() }, { status: 201 });
}
